rutor &lt;- readRDS(here::here("data", "bef_forandring_ruta.rds")) |&gt;
  filter(!str_detect(ruta_id, "^0\\s"), forandring != 0) |&gt;
  mutate(
    northing = as.numeric(str_extract(ruta_id, "^\\d+")),
    easting  = as.numeric(str_extract(ruta_id, "\\d+$"))
  ) |&gt;
  filter(!is.na(northing), !is.na(easting),
         northing &gt;= 6240000, northing &lt;= 6395000,
